        assert_eq!(size_of::<DwSignals>(), 8);
        assert_eq!(align_of::<DwSignals>(), 8);
        assert_eq!(size_of::<DwUserAddress>(), 8);
        assert_eq!(align_of::<DwUserAddress>(), 8);
        assert_eq!(size_of::<DwDeadline>(), 8);
        assert_eq!(align_of::<DwDeadline>(), 8);
        assert_eq!(size_of::<DwHandleTransferOperation>(), 4);
        assert_eq!(align_of::<DwHandleTransferOperation>(), 4);
